// =========================================================
// JA-ORE — "With our powers combined" pixel-cinema
//
// The uploaded JA-ore artwork is embedded as a CSS data URI so the
// project contains NO separate image asset. The rest of the scene is
// generated with CSS + canvas: sunset bands, chunky pixel silhouettes,
// combination beams, impact frames, scanlines and the final ore reveal.
// =========================================================

import { rarityLabel, escapeHtml } from "./format.js";
import { chanceLabelForResult } from "../logic/chances.js";

let injected = false;
const JA_ORE_DATA_URI = "data:image/png;base64,";

function injectStyles() {
  if (injected) return;
  injected = true;
  const style = document.createElement("style");
  style.textContent = `
    #ja-ore-cutscene{position:fixed;inset:0;z-index:1100;overflow:hidden;opacity:0;background:#120914;transition:opacity .45s ease;isolation:isolate}
    #ja-ore-cutscene.is-playing{opacity:1}
    #ja-ore-cutscene::before{content:"";position:absolute;inset:0;background:linear-gradient(180deg,#20112f 0%,#5d205e 28%,#d95770 50%,#ff9d55 64%,#2c1b42 78%,#0d0918 100%);z-index:-5}
    #ja-ore-cutscene::after{content:"";position:absolute;inset:0;background:radial-gradient(circle at 50% 54%,rgba(255,229,115,.38),transparent 16%),radial-gradient(circle at 50% 70%,rgba(255,103,92,.24),transparent 38%),linear-gradient(90deg,rgba(0,0,0,.32),transparent 20%,transparent 80%,rgba(0,0,0,.42));pointer-events:none;z-index:8}
    .ja-canvas{position:absolute;inset:0;width:100%;height:100%;image-rendering:pixelated;z-index:0}
    .ja-sky-grid{position:absolute;inset:0;z-index:1;opacity:.22;background:linear-gradient(rgba(255,255,255,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.05) 1px,transparent 1px);background-size:24px 24px;mask-image:linear-gradient(transparent 20%,#000 64%,transparent 100%)}
    .ja-rays{position:absolute;inset:-20%;z-index:2;opacity:.55;background:conic-gradient(from 250deg at 50% 58%,transparent 0 10deg,rgba(255,245,161,.13) 11deg 15deg,transparent 16deg 28deg,rgba(99,255,230,.10) 29deg 35deg,transparent 36deg 53deg,rgba(222,104,255,.11) 54deg 60deg,transparent 61deg 360deg);animation:jaRays 9s linear infinite}
    .ja-pixel-dust{position:absolute;inset:0;z-index:4;pointer-events:none;background-image:radial-gradient(circle,rgba(255,239,153,.9) 0 2px,transparent 2.5px),radial-gradient(circle,rgba(101,255,224,.8) 0 1px,transparent 2px);background-size:67px 83px,43px 71px;background-position:13px 9px,31px 17px;animation:jaDust 5s linear infinite}
    .ja-letterbox{position:absolute;left:0;right:0;height:0;background:#06050b;z-index:20;transition:height .75s cubic-bezier(.7,0,.2,1)}
    .ja-letterbox.top{top:0} .ja-letterbox.bottom{bottom:0}
    #ja-ore-cutscene.cine .ja-letterbox{height:9vh}
    .ja-spirits{position:absolute;inset:0;z-index:5;pointer-events:none}
    .ja-spirit{position:absolute;width:clamp(110px,14vw,190px);height:clamp(180px,25vw,310px);opacity:0;filter:drop-shadow(0 0 20px currentColor);animation:jaSpiritIn 1.1s cubic-bezier(.16,1,.3,1) forwards}
    .ja-spirit::before,.ja-spirit::after{content:"";position:absolute;image-rendering:pixelated;background:currentColor;box-shadow:0 0 0 7px currentColor}
    .ja-spirit::before{left:34%;top:17%;width:32%;height:23%;clip-path:polygon(20% 0,80% 0,100% 30%,88% 100%,12% 100%,0 30%)}
    .ja-spirit::after{left:20%;top:38%;width:60%;height:39%;clip-path:polygon(20% 0,80% 0,100% 22%,74% 40%,91% 100%,60% 100%,50% 61%,40% 100%,9% 100%,26% 40%,0 22%)}
    .ja-spirit--a{left:9%;top:43%;color:#6be8ff;animation-delay:.35s}
    .ja-spirit--b{left:43%;top:29%;color:#9b73ff;animation-delay:.7s;transform:scale(1.12)}
    .ja-spirit--c{right:9%;top:43%;color:#f4e36e;animation-delay:1.05s}
    .ja-spirit::marker{display:none}
    .ja-spirit span{position:absolute;left:28%;top:59%;width:12%;height:5%;background:#101018;box-shadow:34px 0 #101018,17px 20px #101018;opacity:.85}
    .ja-combine{position:absolute;left:50%;top:51%;width:4px;height:4px;background:#fff7a0;box-shadow:0 0 10px #fff7a0;opacity:0;z-index:7;transform:translate(-50%,-50%)}
    .ja-combine::before,.ja-combine::after{content:"";position:absolute;left:50%;top:50%;width:44vw;height:4px;transform-origin:left center;background:linear-gradient(90deg,transparent,rgba(255,255,255,.95),rgba(107,255,226,.75),transparent);box-shadow:0 0 24px rgba(255,255,255,.85);transform:translateY(-50%) rotate(var(--a)) scaleX(0);animation:jaBeam 1.8s .2s cubic-bezier(.2,.9,.2,1) forwards}
    .ja-combine::before{--a:198deg} .ja-combine::after{--a:342deg}
    .ja-ore-card{position:absolute;left:50%;top:49%;width:min(34vw,380px);aspect-ratio:1/1.08;transform:translate(-50%,-50%) scale(.2) rotate(-8deg);opacity:0;z-index:10;display:grid;place-items:center;transition:transform 1.1s cubic-bezier(.16,1,.3,1),opacity .7s ease;filter:drop-shadow(0 0 20px rgba(255,225,63,.8)) drop-shadow(0 0 65px rgba(255,115,50,.55))}
    .ja-ore-card.show{opacity:1;transform:translate(-50%,-50%) scale(1) rotate(0deg)}
    .ja-ore-card::before{content:"";position:absolute;inset:-14%;border:3px solid rgba(255,232,91,.7);clip-path:polygon(16% 0,84% 0,100% 16%,100% 84%,84% 100%,16% 100%,0 84%,0 16%);box-shadow:0 0 30px rgba(255,225,65,.6),inset 0 0 25px rgba(255,160,45,.35);animation:jaOrbit 5s linear infinite}
    .ja-ore-art{width:76%;height:76%;object-fit:contain;image-rendering:pixelated;filter:contrast(1.12) saturate(1.15) drop-shadow(0 0 9px rgba(255,215,54,.8));mix-blend-mode:multiply}
    .ja-ore-glow{position:absolute;width:68%;height:68%;border-radius:50%;background:radial-gradient(circle,rgba(255,246,147,.65),rgba(255,182,36,.25) 40%,transparent 70%);mix-blend-mode:screen;animation:jaPulse 1.4s ease-in-out infinite}
    .ja-copy{position:absolute;left:0;right:0;bottom:12vh;z-index:30;text-align:center;pointer-events:none;padding:0 20px}
    .ja-copy>*{opacity:0;transform:translateY(22px) scale(.92);filter:blur(8px);transition:opacity .65s ease,transform .9s cubic-bezier(.16,1,.3,1),filter .65s ease}
    .ja-copy .show{opacity:1;transform:none;filter:none}
    .ja-kicker{font:800 clamp(.7rem,1.6vw,1rem)/1 var(--font-mono,monospace);letter-spacing:.48em;text-transform:uppercase;color:#ffe889;text-shadow:0 0 18px #ff724d,0 0 40px rgba(255,210,69,.7)}
    .ja-title{position:relative;margin:9px auto 0;width:max-content;max-width:94vw;font:950 clamp(2.7rem,9vw,7.2rem)/.86 var(--font-display,Orbitron,sans-serif);letter-spacing:.02em;text-transform:uppercase;background:linear-gradient(180deg,#fffbe0 0%,#ffe347 31%,#ff9c3e 62%,#ff4d5e 82%,#b95cff 100%);-webkit-background-clip:text;background-clip:text;color:transparent;text-shadow:0 0 1px #fff,0 0 20px rgba(255,221,71,.9),0 0 65px rgba(255,77,93,.65)}
    .ja-title::before,.ja-title::after{content:"JA-ORE";position:absolute;inset:0;z-index:-1;color:transparent;-webkit-text-stroke:2px rgba(255,255,255,.12);filter:blur(2px);animation:jaTextJitter 1.2s steps(2,end) infinite}
    .ja-title::before{transform:translate(5px,-3px);text-shadow:-6px 0 rgba(101,255,224,.45)}
    .ja-title::after{transform:translate(-5px,3px);text-shadow:6px 0 rgba(255,91,112,.4)}
    .ja-phrase{margin:12px auto 0;font:950 clamp(1.1rem,3.3vw,2.2rem)/1.05 var(--font-display,Orbitron,sans-serif);letter-spacing:.08em;text-transform:uppercase;color:#fff6c7;text-shadow:0 0 4px #fff,0 0 16px #ffbd43,0 0 35px rgba(255,92,83,.9);max-width:1000px}
    .ja-phrase::before,.ja-phrase::after{content:"";display:inline-block;width:clamp(28px,8vw,120px);height:3px;vertical-align:middle;margin:0 12px;background:linear-gradient(90deg,transparent,#fff0a3,transparent);box-shadow:0 0 10px #ffd95b}
    .ja-sub{margin-top:11px;font:800 clamp(.75rem,1.8vw,1.1rem)/1.2 var(--font-mono,monospace);color:#ffe6bd;letter-spacing:.16em;text-transform:uppercase;text-shadow:0 0 14px #ff805c}
    .ja-chance{margin-top:7px;font:650 clamp(.68rem,1.5vw,.95rem)/1.2 var(--font-mono,monospace);color:#d9faff;letter-spacing:.08em}
    .ja-muts{display:flex;justify-content:center;gap:9px;flex-wrap:wrap;margin-top:10px;font:850 .76rem/1 var(--font-mono,monospace);letter-spacing:.13em;text-transform:uppercase;color:#a8fff0}
    .ja-muts .dot{opacity:.5;color:#ffe37a}
    .ja-flash{position:absolute;inset:0;background:#fffbd0;z-index:40;opacity:0;pointer-events:none;mix-blend-mode:screen}
    #ja-ore-cutscene.flash .ja-flash{animation:jaFlash .5s ease-out}
    .ja-scanlines{position:absolute;inset:0;z-index:50;pointer-events:none;opacity:.17;background:repeating-linear-gradient(0deg,transparent 0 3px,rgba(255,255,255,.11) 3px 4px);mix-blend-mode:overlay}
    .ja-vignette{position:absolute;inset:0;z-index:51;pointer-events:none;background:radial-gradient(circle at 50% 52%,transparent 30%,rgba(7,2,17,.18) 62%,rgba(3,1,8,.78) 100%)}
    @keyframes jaRays{to{transform:rotate(360deg)}}
    @keyframes jaDust{to{background-position:113px 89px,91px 101px}}
    @keyframes jaSpiritIn{from{opacity:0;transform:translateY(25px) scale(.7)}to{opacity:.82;transform:translateY(0) scale(1)}}
    @keyframes jaBeam{to{transform:translateY(-50%) rotate(var(--a)) scaleX(1)}}
    @keyframes jaOrbit{to{transform:rotate(360deg)}}
    @keyframes jaPulse{50%{transform:scale(1.18);opacity:.75}}
    @keyframes jaFlash{0%{opacity:0}20%{opacity:.95}100%{opacity:0}}
    @keyframes jaTextJitter{0%,90%{clip-path:inset(0)}92%{clip-path:inset(35% 0 48% 0)}96%{clip-path:inset(63% 0 12% 0)}100%{clip-path:inset(0)}}
    @media(max-width:700px){.ja-spirit{transform:scale(.7)}.ja-ore-card{width:min(58vw,330px)}.ja-copy{bottom:11vh}.ja-title{font-size:clamp(2.4rem,13vw,5rem)}.ja-phrase::before,.ja-phrase::after{display:none}}
    @media(prefers-reduced-motion:reduce){.ja-rays,.ja-pixel-dust,.ja-title::before,.ja-title::after,.ja-ore-card::before,.ja-ore-glow{animation:none!important}.ja-canvas{display:none}.ja-copy>*{transition:none}}
  `;
  document.head.appendChild(style);
}

export function buildJaOreCutscene(data, outcome, duration = 15000) {
  injectStyles();
  document.getElementById("ja-ore-cutscene")?.remove();
  const D = Math.max(10000, Number(duration) || 15000);
  const mutations = Array.isArray(data?.mutations) ? data.mutations : [];
  const overlay = document.createElement("div");
  overlay.id = "ja-ore-cutscene";
  overlay.innerHTML = `
    <canvas class="ja-canvas"></canvas>
    <div class="ja-sky-grid"></div><div class="ja-rays"></div><div class="ja-pixel-dust"></div>
    <div class="ja-spirits" aria-hidden="true"><div class="ja-spirit ja-spirit--a"><span></span></div><div class="ja-spirit ja-spirit--b"><span></span></div><div class="ja-spirit ja-spirit--c"><span></span></div></div>
    <div class="ja-combine" aria-hidden="true"></div>
    <div class="ja-ore-card" data-ja="ore"><div class="ja-ore-glow"></div><img class="ja-ore-art" alt="JA-ore" src="${JA_ORE_DATA_URI}"></div>
    <div class="ja-flash"></div><div class="ja-scanlines"></div><div class="ja-vignette"></div>
    <div class="ja-copy">
      <div class="ja-kicker" data-ja="kicker">When the roll reaches the impossible</div>
      <div class="ja-title" data-ja="title">JA-ORE</div>
      <div class="ja-phrase" data-ja="phrase">With our powers combined</div>
      <div class="ja-sub" data-ja="sub">${escapeHtml(rarityLabel(data?.gem?.rarity ?? 6242026))}</div>
      ${mutations.length ? `<div class="ja-muts" data-ja="muts">${mutations.map((m,i)=>`${i?'<span class="dot">·</span>':''}<span>${escapeHtml(m.name)}</span>`).join("")}</div>` : ""}
      <div class="ja-chance" data-ja="chance">Actual chance: ${escapeHtml(chanceLabelForResult(String(data?.gem?.name ?? "Ja-ore"), mutations.map(m=>m.id)))}</div>
    </div>
    <div class="ja-letterbox top"></div><div class="ja-letterbox bottom"></div>
  `;
  document.body.appendChild(overlay);
  requestAnimationFrame(() => overlay.classList.add("is-playing"));

  const canvas = overlay.querySelector(".ja-canvas");
  const ctx = canvas.getContext("2d");
  let W=0,H=0,DPR=1,raf=0;
  const sparks = Array.from({length:220},()=>({x:Math.random(),y:.15+Math.random()*.68,s:1+Math.random()*4,p:Math.random()*Math.PI*2,sp:.4+Math.random()*1.6}));
  function resize(){DPR=Math.min(2,devicePixelRatio||1);W=innerWidth;H=innerHeight;canvas.width=W*DPR;canvas.height=H*DPR;ctx.setTransform(DPR,0,0,DPR,0,0)}
  resize(); addEventListener("resize",resize);
  const start=performance.now();
  const clamp=t=>Math.max(0,Math.min(1,t));
  const smooth=t=>{t=clamp(t);return t*t*(3-2*t)};
  const win=(t,a,b)=>smooth((t-a)/(b-a));
  function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
  function frame(now){
    if(!document.body.contains(overlay)){cancelAnimationFrame(raf);removeEventListener("resize",resize);return}
    const t=now-start,p=clamp(t/D),end=1-smooth((t-D+1000)/1000);
    ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,W,H);
    const bands=[["#251437",0,.16],["#60205e",.16,.32],["#b94a6a",.32,.49],["#ee6a5b",.49,.61],["#ffc45d",.61,.69],["#56345d",.69,.79],["#160d26",.79,1]];
    for(const [c,a,b] of bands)rect(0,H*a,W,H*(b-a)+2,c);
    ctx.globalAlpha=.95;ctx.fillStyle="#ffe47a";ctx.beginPath();ctx.arc(W*.5,H*.63,Math.min(W,H)*.105,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
    rect(0,H*.72,W,H*.07,"#3b2447");rect(0,H*.79,W,H*.21,"#160d26");
    for(let i=0;i<22;i++){const x=(i/22)*W;const h=(.025+.09*((i*13)%11)/11)*H;rect(x,H*.72-h,Math.max(18,W/30),h,"#2d1940")}
    const pulse=win(t,D*.05,D*.32);
    for(const s of sparks){const drift=Math.sin(now*.001*s.sp+s.p)*18;const sy=s.y*H+Math.sin(now*.002*s.sp+s.p)*11;ctx.globalAlpha=(.12+.75*pulse)*(1-.25*p);rect(s.x*W+drift,sy,s.s,s.s,s.sp>1.3?"#ffe17c":s.sp>.8?"#70fff0":"#d86cff")}
    ctx.globalAlpha=1;
    // Combination pulse: three energy lanes converge on the center.
    if(t>D*.28&&t<D*.66){const q=win(t,D*.28,D*.66);const cx=W*.5,cy=H*.52;ctx.globalAlpha=.28+.55*(1-q);for(let i=0;i<3;i++){const sx=[W*.22,W*.5,W*.78][i],sy=[H*.55,H*.38,H*.55][i];ctx.strokeStyle=["#69efff","#a878ff","#f4e66d"][i];ctx.lineWidth=3+5*(1-q);ctx.beginPath();ctx.moveTo(sx,sy);ctx.lineTo(cx+(i-1)*20,cy);ctx.stroke()}ctx.globalAlpha=1}
    if(t>D*.56&&t<D*.76){overlay.classList.add("flash");}
    const beats={kicker:D*.20,title:D*.31,phrase:D*.48,ore:D*.57,sub:D*.68,muts:D*.74,chance:D*.79};
    for(const el of overlay.querySelectorAll("[data-ja]"))el.classList.toggle("show",t>=(beats[el.dataset.ja]??9e9)&&t<D-.65e3);
    overlay.classList.toggle("cine",t>D*.07&&t<D-.7e3);
    if(t>D*.52)overlay.querySelector(".ja-ore-card")?.classList.add("show");
    if(t>D-700)overlay.style.opacity=String(end);
    raf=requestAnimationFrame(frame);
  }
  raf=requestAnimationFrame(frame);
  return overlay;
}
